from donations import load_donations, ROWS
from changes import pounds_changes, biggest_rise

VALUES = [v for _, v in ROWS]
EXPECTED = [VALUES[i] - VALUES[i - 1] for i in range(1, len(VALUES))]


def test_number_of_changes():
    assert len(pounds_changes(list(load_donations()))) == len(ROWS) - 1


def test_values():
    assert pounds_changes(list(load_donations())) == EXPECTED


def test_two_items():
    assert pounds_changes(list(load_donations())[:2]) == EXPECTED[:1]


def test_biggest_rise():
    assert biggest_rise(list(load_donations())) == max([c for c in EXPECTED if c > 0] or [0])


def test_single_item():
    assert pounds_changes(list(load_donations())[:1]) == [] and pounds_changes([]) == []

